ccount_code, sum(coalesce(etd.ta_reclassification_amount, 0)) as ta_reclassification_amount from eg_ta_reclassification et inner join eg_ta_reclassification_detail etd on et.id = etd.ta_reclassification_id where et.del_flag = '0' and etd.del_flag = '0' and et.process_status in ('2', '3', '4') and to_char(et.reclassification_month, 'yyyy-MM') = #{params.checkingMonth} and coalesce(etd.ta_reclassification_amount, 0)!=0 group by to_char(et.reclassification_month, 'yyyy-MM'), etd.ebank_batch_no union all select to_char(et.reclassification_month, 'yyyy-MM') as reclassification_month, etd.ebank_batch_no, max(etd.account_code) ta_account_code, sum(coalesce(etd.reclassification_amount, 0)) as reclassification_amount from eg_ta_other_payable et inner join eg_ta_other_payable_detail etd on et.id = etd.ta_other_payable_id where et.del_flag = '0' and etd.del_flag = '0' and et.process_status in ('2', '3', '4') and to_char(et.reclassification_month, 'yyyy-MM') = #{params.checkingMonth} and coalesce(etd.reclassification_amount, 0)!=0 group by to_char(et.reclassification_month, 'yyyy-MM'), etd.ebank_batch_no) t1 group by t1.reclassification_month, t1.ebank_batch_no ), report_balance as ( select ebank_batch_no as ebank_serial_number, 'CYCXT' as system_code, sum(coalesce (ta_excess_balance, 0)) as ta_excess_balance from ta_cyc tc group by ebank_batch_no , system_code union all select ebank_batch_no as ebank_serial_number, 'SYCXT' as system_code, sum(coalesce (ta_excess_balance, 0)) as ta_excess_balance from ta_syc ts group by ebank_batch_no , system_code union all select ebank_serial_number, 'TYPT' as system_code, sum(coalesce (ta_excess_balance, 0)) as ta_excess_balance from ta_typt tt group by ebank_serial_number , system_code union all select ebank_serial_number, 'XWXT' as system_code, sum(coalesce (ta_excess_balance, 0)) as ta_excess_balance from ta_xw tx group by ebank_serial_number , system_code union all select ebank_serial_number, 'YYPT' as system_code, sum(coalesce (ta_exces